from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

def Temperature_for_location():
    try:
        # 获取请求中的参数
        latitude = request.args.get('latitude')
        longitude = request.args.get('longitude')
        date = request.args.get('date')

        # 检查参数是否完整
        if not latitude or not longitude or not date:
            return jsonify({"error": "Missing required parameters: latitude, longitude, date"}), 400

        # 连接数据库
        conn = sqlite3.connect('weather.db')
        cursor = conn.cursor()

        # 执行查询
        query = """
        SELECT temperature FROM weather_data 
        WHERE latitude = ? AND longitude = ? AND date = ?
        """
        cursor.execute(query, (latitude, longitude, date))
        result = cursor.fetchone()

        # 关闭数据库连接
        conn.close()

        # 返回结果
        if result:
            return jsonify({"temperature": result[0]})
        else:
            return jsonify({"error": "No data found for the given location and date"}), 404

    except sqlite3.Error as e:
        return jsonify({"error": f"Database error: {str(e)}"}), 500
    except Exception as e:
        return jsonify({"error": f"Unexpected error: {str(e)}"}), 500

# 路由
@app.route('/api/Temperature_for_location', methods=['GET'])
def api_Temperature_for_location():
    return Temperature_for_location()

if __name__ == '__main__':
    app.run(debug=True)

