app = Flask(__name__)

@app.route('/api/temperature_for_location', methods=['GET'])
def temperature_for_location():
    # الحصول على المعطيات من الطلب
    latitude = request.args.get('latitude')
    longitude = request.args.get('longitude')
    date = request.args.get('date')

    # التحقق من وجود المعطيات المطلوبة
    if not latitude or not longitude or not date:
        return jsonify({'error': 'Missing required parameters: latitude, longitude, date'}), 400

    try:
        # الاتصال بقاعدة البيانات
        conn = sqlite3.connect('weather_data.db')
        cursor = conn.cursor()

        # تنفيذ الاستعلام للحصول على درجة الحرارة
        cursor.execute('''
            SELECT temperature FROM weather 
            WHERE latitude = ? AND longitude = ? AND date = ?
        ''', (latitude, longitude, date))

        result = cursor.fetchone()
        conn.close()

        # إرجاع درجة الحرارة أو None إذا لم توجد بيانات
        if result:
            return jsonify({'temperature': result[0]})
        else:
            return jsonify({'temperature': None})

    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

